      "titleTh": "แรงนิวเคลียร์อย่างเข้ม แถบเสถียรภาพ และเลขมหัศจรรย์",
      "titleEn": "Strong Nuclear Force, Stability Belt & Magic Numbers",
      "summary": "แรงนิวเคลียร์อย่างเข้มเป็นกาวเหนี่ยวรั้งโปรตอนไว้ด้วยกัน นิวเคลียสที่เสถียรต้องมีสัดส่วน $N/Z$ ที่เหมาะสมและนิวเคลียสที่มีเลขมหัศจรรย์จะเสถียรเป็นพิเศษ",
      "definition": {
        "text": "แรงนิวเคลียร์อย่างเข้ม (Strong Nuclear Force) คือแรงดึงดูดมูลฐานที่รุนแรงที่สุดในธรรมชาติ ทำหน้าที่ยึดเหนี่ยวนิวคลีออน (โปรตอนและนิวตรอน) ให้อยู่ร่วมกันในนิวเคลียส เอาชนะแรงผลักทางไฟฟ้าคูลอมบ์มหาศาลระหว่างโปรตอนด้วยกัน มีคุณสมบัติสำคัญคือ: 1) เป็นแรงระยะสั้นมาก (Short-range, มีผลเฉพาะในระยะ ~1-2 fm) 2) มีสภาพอิ่มตัว (Saturation) คือนิวคลีออนตัวหนึ่งจะดูดเฉพาะเพื่อนบ้านใกล้เคียงเท่านั้น 3) เป็นอิสระจากประจุไฟฟ้า (Charge independence, แรง p-p, n-n, p-n เท่ากัน) นิวเคลียสที่เสถียรในธรรมชาติจะเรียงตัวอยู่บน 'แถบความเสถียร' (Belt of Stability หรือ Segrè Chart)"
      },
      "principle": {
        "text": "การจดจำและรูปแบบทางกายภาพ (Intuitive Mental Model):\n1. นิวตรอนทำหน้าที่เป็น 'กาวกันชน': โปรตอนมีประจุบวกจึงผลักกัน ยิ่งนิวเคลียสใหญ่ขึ้น แรงผลักไฟฟ้าผลักกันทุกตัว (Long-range) แต่แรงดึงดูดนิวเคลียร์ดึงเฉพาะตัวติดกัน (Short-range) ธรรมชาติจึงต้องใส่ 'นิวตรอน' เข้ามาเพิ่มเนื้อกาวโดยไม่เพิ่มแรงผลัก\n   - ธาตุเบา (Z < 20): อัตราส่วน N/Z ≈ 1.0 (เช่น ¹²C มี 6p, 6n)\n   - ธาตุหนัก (Z ~ 80): อัตราส่วน N/Z พุ่งขึ้นเป็น ≈ 1.5 (เช่น ²⁰⁸Pb มี 82p, 126n)\n   - ถ้า Z > 82 (บิสมัทและยูเรเนียมขึ้นไป): ไม่มีนิวเคลียสใดเสถียรอีกต่อไป ทุกตัวจะแผ่รังสีสลายตัวหมด!\n2. นิวเคลียสที่อยู่นอกแถบเสถียรภาพ:\n   - อยู่เหนือกราฟ (นิวตรอนมากเกินไป): จะสลายตัวแบบ บีตาลบ (β⁻) โดยเปลี่ยนนิวตรอนเป็นโปรตอน\n   - อยู่ใต้กราฟ (โปรตอนมากเกินไป): จะสลายตัวแบบ บีตาบวก (β⁺) หรือจับยึดอิเล็กตรอน (EC)\n3. เลขมหัศจรรย์ (Magic Numbers): นิวเคลียสที่มีจำนวนโปรตอนหรือนิวตรอนเท่ากับ 2, 8, 20, 28, 50, 82, 126 จะมีเสถียรภาพสูงลิบลิ่วเหมือนแก๊สเฉื่อยในเคมี นิวเคลียสที่มีทั้ง Z และ N เป็นเลขมหัศจรรย์คู่กันเรียกว่า 'Doubly Magic' เช่น ⁴He (2p, 2n), ¹⁶O (8p, 8n), ²⁰⁸Pb (82p, 126n)"
      },
