      "divisionTitle": "ภาคที่ 4: ปฏิกิริยานิวเคลียร์ ฟิชชัน ฟิวชัน อนุภาคมูลฐาน และความปลอดภัยทางรังสี",
      "numberTh": "ทฤษฎีที่ 18",
      "type": "ทฤษฎีรากฐาน",
      "titleTh": "ปฏิกิริยานิวเคลียร์ กฎการอนุรักษ์ และค่า Q-Value",
      "titleEn": "Nuclear Reactions, Conservation Laws & Q-Value",
      "summary": "การชนแปลงธาตุระดับนิวเคลียส ต้องอนุรักษ์นิวคลีออนรวม ประจุไฟฟ้า โมเมนตัม และพลังงานสัมพัทธภาพ โดยค่า $Q > 0$ คายพลังงาน และ $Q < 0$ ดูดกลืนพลังงาน",
      "definition": {
        "text": "ปฏิกิริยานิวเคลียร์ (Nuclear Reaction) คือกระบวนการที่นิวเคลียสเป้าหมาย (Target: X) ถูกชนโดยอนุภาคกระสุนพุ่งชน (Projectile: a) ทำให้เกิดการแปรธาตุกลายเป็นนิวเคลียสใหม่ (Residual: Y) และปลดปล่อยอนุภาคชนิดใหม่ออกมา (Ejectile: b) เขียนในรูปสัญลักษณ์ย่อว่า $X(a,b)Y$ ในทุกปฏิกิริยานิวเคลียร์ต้องเป็นไปตามกฎการอนุรักษ์ 4 ประการอย่างเคร่งครัด: 1) อนุรักษ์เลขมวลรวม $\\sum A$ 2) อนุรักษ์ประจุไฟฟ้ารวม $\\sum Z$ 3) อนุรักษ์โมเมนตัมเชิงเส้นและเชิงมุม 4) อนุรักษ์พลังงานสัมพัทธภาพรวม ค่าพลังงานของปฏิกิริยาเรียกว่า 'ค่า Q' (Q-Value): $Q = (m_{\\text{initial}} - m_{\\text{final}})c^2$"
      },
      "principle": {
        "text": "การจดจำและรูปแบบทางกายภาพ (Intuitive Mental Model):\n1. ความหมายของค่า Q:\n   - ปฏิกิริยาคายพลังงาน (Exoergic: Q > 0): มวลหลังปฏิกิริยาน้อยกว่ามวลเริ่มต้น มวลที่หายไปถูกแปลงเป็นพลังงานจลน์พุ่งพรวดออกมา เกิดขึ้นได้เองทันทีเมื่ออนุภาคชนกัน\n   - ปฏิกิริยาดูดกลืนพลังงาน (Endoergic: Q < 0): มวลหลังปฏิกิริยามากกว่ามวลเริ่มต้น ต้องใช้พลังงานจลน์จากภายนอกมาเติมเต็มส่วนต่างมวล อนุภาคกระสุนต้องมี 'พลังงานจลน์ขั้นต่ำ' (Threshold Energy: $K_{\\text{th}} = |Q|(1 + m_a / M_X)$) จึงจะเกิดปฏิกิริยาได้\n2. ปฏิกิริยานิวเคลียร์ครั้งแรกของมนุษยชาติ (Rutherford, 1919):\n   เออร์เนสต์ รัทเทอร์ฟอร์ด ยิงอนุภาคแอลฟาพุ่งชนแก๊สไนโตรเจน-14 เกิดเป็นออกซิเจน-17 และ 'โปรตอน': $^{14}_7\\text{N}(\\alpha, p)^{17}_8\\text{O}$ นี่คือความฝันของนักเล่นแร่แปรธาตุยุคโบราณที่กลายเป็นจริงด้วยฟิสิกส์นิวเคลียร์!"
      },
