          "derivationSteps": [
            "อนุรักษ์พลังงานสัมพัทธภาพรวม: (m_a c² + K_a) + M_X c² = (m_b c² + K_b) + (M_Y c² + K_Y)",
            "จัดรูปย้ายข้าง: (K_b + K_Y) - K_a = (m_a + M_X - m_b - M_Y) c²",
            "นิยามพลังงานจลน์สุทธิที่ได้รับเพิ่มขึ้นคือ Q = K_final - K_initial = (M_initial - M_final) c²"
          ]
