      "numberTh": "ทฤษฎีที่ 19",
      "type": "ทฤษฎีประยุกต์",
      "titleTh": "ปฏิกิริยานิวเคลียร์ฟิชชันและปฏิกิริยาลูกโซ่",
      "titleEn": "Nuclear Fission, Chain Reactions & Critical Mass",
      "summary": "การผ่าซีกนิวเคลียสยูเรเนียม-235 ด้วยนิวตรอนช้า ปลดปล่อยพลังงาน 200 MeV ต่อฟิชชัน และพ่นนิวตรอนใหม่ออกมา 2-3 ตัวเพื่อขับเคลื่อนปฏิกิริยาลูกโซ่โรงไฟฟ้านิวเคลียร์",
      "definition": {
        "text": "ปฏิกิริยานิวเคลียร์ฟิชชัน (Nuclear Fission, ค้นพบโดย ออตโต ฮาห์น และ ฟริตซ์ สตราสมันน์, 1938) คือปรากฏการณ์ที่นิวเคลียสหนักที่ไม่เสถียร เช่น ยูเรเนียม-235 ($^{235}\\text{U}$) หรือ พลูโทเนียม-239 ($^{239}\\text{Pu}$) ดูดกลืนนิวตรอนช้า (Thermal Neutron, พลังงาน ~0.025 eV) กลายเป็นสถานะกระตุ้น $^{236}\\text{U}^*$ แล้วแตกตัวออกเป็นสองนิวเคลียสขนาดกลาง (Fission Fragments เช่น แบเรียมและคริปตอน) พร้อมกับปลดปล่อยพลังงานมหาศาลประมาณ 200 MeV ต่อครั้ง และพ่นนิวตรอนอิสระตัวใหม่ออกมาเฉลี่ย 2.4-2.5 ตัว นิวตรอนที่เกิดขึ้นใหม่เหล่านี้สามารถพุ่งไปชนอะตอมยูเรเนียมข้างเคียงต่อ นำไปสู่ 'ปฏิกิริยาลูกโซ่' (Chain Reaction) ที่ต่อเนื่องไม่รู้จบ"
      },
      "principle": {
        "text": "การจดจำและรูปแบบทางกายภาพ (Intuitive Mental Model):\n1. ทำไมฟิชชันถึงให้พลังงานบ้าคลั่งขนาดนี้? น้ำมันเบนซิน 1 ลิตรเผาไหม้ทางเคมีปล่อยพลังงาน ~34 ล้านจูล แต่ ยูเรเนียม-235 ขนาดเท่า 'เม็ดยางลบก้อนเล็กๆ หนัก 1 กรัม' เกิดฟิชชันจะปล่อยพลังงานถึง ~8.2 × 10¹⁰ จูล (เทียบเท่าน้ำมันเบนซินกว่า 2,400 ลิตร หรือถ่านหินหินถึง 3 ตัน!)\n2. ตัวประกอบทวีคูณนิวตรอน (Multiplication Factor, k):\n   - k < 1 (Subcritical): นิวตรอนรุ่นใหม่น้อยกว่ารุ่นเก่า ปฏิกิริยาค่อยๆ มอดดับลง\n   - k = 1.000 (Critical): ปฏิกิริยาคงที่สม่ำเสมอ พลังงานออกคงที่พอดี นี่คือหัวใจของ 'โรงไฟฟ้านิวเคลียร์พลเรือน' ที่ปลอดภัยสมบูรณ์แบบ\n   - k > 1 (Supercritical): นิวตรอนทวีคูณแบบเอ็กซ์โพเนนเชียลในเสี้ยวไมโครวินาที นี่คือ 'ระเบิดนิวเคลียร์ฟิชชัน' (Atomic Bomb)\n3. 3 เสาหลักของเครื่องปฏิกรณ์นิวเคลียร์:\n   - เชื้อเพลิง (Fuel): ยูเรเนียมเสริมสมรรถนะ (Enriched Uranium ²³⁵U 3-5% สำหรับโรงไฟฟ้า, ไม่ใช่ 90% แบบระเบิด)\n   - สารหน่วงนิวตรอน (Moderator): น้ำธรรมดา (Light Water) หรือแกรไฟต์ ทำหน้าที่ชะลอนิวตรอนเร็ว (Fast neutron) ให้เป็นนิวตรอนช้า เพื่อให้ยูเรเนียมดูดกลืนได้ดีขึ้น\n   - แท่งควบคุม (Control Rods): ทำจากโบรอน (B) หรือแคดเมียม (Cd) ที่กลืนกินนิวตรอนได้ดีเยี่ยม เสียบเข้าแกนปฏิกรณ์เพื่อเบรกปฏิกิริยา และถอนออกเพื่อเร่งกำลัง"
      },
