          "name": "สมการปฏิกิริยาฟิชชันของยูเรเนียม-235 (U-235 Fission Equation)",
          "desc": "ตัวอย่างการแตกตัวของยูเรเนียม-235 เมื่อได้รับนิวตรอนความร้อน",
