      "summary": "แหล่งพลังงานสูงสุดของจักรวาล: การหลอมรวมนิวเคลียสเบาให้เป็นนิวเคลียสหนัก ณ อุณหภูมิหลักร้อยล้านองศา เชื้อเพลิงสะอาดไร้กากกัมมันตรังสีอายุยืน",
      "definition": {
        "text": "ปฏิกิริยานิวเคลียร์ฟิวชัน (Nuclear Fusion) คือกระบวนการที่นิวเคลียสเบาตั้งแต่สองตัวขึ้นไป เช่น ดิวเทอเรียม ($^2_1\\text{H}$) และ ทริเทียม ($^3_1\\text{H}$) เคลื่อนที่ด้วยความเร็วสูงยิ่งจนเอาชนะแรงผลักไฟฟ้าคูลอมบ์ แล้วหลอมรวมกันกลายเป็นนิวเคลียสที่หนักกว่าและเสถียรกว่า (ฮีเลียม-4) พร้อมปลดปล่อยพลังงานมหาศาลต่อน้ำหนักมากกว่าฟิชชันถึง 4 เท่า ปฏิกิริยานี้คือขุมพลังงานที่ส่องสว่างดวงอาทิตย์และดาวฤกษ์ทุกดวงผ่าน 'วัฏจักรโปรตอน-โปรตอน' (p-p chain) มนุษย์กำลังเลียนแบบพลังงานนี้บนโลกผ่านเครื่องปฏิกรณ์แม่เหล็กรูปทรงโดนัท เรียกว่า 'โทคาแมก' (Tokamak เช่น โครงการเตาปฏิกรณ์ฟิวชันสากล ITER) ภายใต้เกณฑ์ลอว์สัน (Lawson Criterion)"
      },
      "principle": {
        "text": "การจดจำและรูปแบบทางกายภาพ (Intuitive Mental Model):\n1. แดดที่ส่องโลกคือพลังงานฟิวชัน: แกนกลางดวงอาทิตย์อุณหภูมิ 15 ล้านองศาเคลวิน หลอมโปรตอน 600 ล้านตันเป็นฮีเลียม 'ทุกๆ วินาที' โดยมวลหายไป 4 ล้านตันกลายเป็นแสงสว่างเดินทาง 8 นาทีมาสร้างชีวิตบนโลก\n2. ทำไมฟิวชันบนโลกถึงยากเย็นแสนเข็ญ? นิวเคลียสทั้งสองมีประจุบวก เมื่อเข้าใกล้กันจะผลักกันอย่างบ้าคลั่งด้วยแรงคูลอมบ์ การจะจับมันชนกันจนแรงเข้มดูดติดได้ ต้องเผาแก๊สจนกลายเป็น 'พลาสมา' อุณหภูมิสูงกว่า 100-150 ล้านองศาเซลเซียส (ร้อนกว่าใจกลางดวงอาทิตย์ 10 เท่า! เพราะบนโลกเราไม่มีแรงโน้มถ่วงมหาศาลคอยช่วยบีบอัด)\n3. ขวดแม่เหล็ก (Magnetic Confinement): ไม่มีวัสดุใดในจักรวาลทนความร้อน 150 ล้านองศาได้ ผนังโลหะจะระเหิดเป็นไอทันที นักวิทยาศาสตร์จึงใช้ 'สนามแม่เหล็กบิดเป็นรูปโดนัท' ขังพลาสมาให้ลอยอยู่กลางอากาศในสุญญากาศโดยไม่แตะผนังเตาเลยแม้แต่มิลลิเมตรเดียว!\n4. พลังงานแห่งอนาคตที่ไม่มีวันหมด: เชื้อเพลิงดิวเทอเรียมสกัดได้จากน้ำทะเล น้ำทะเล 1 ลิตร มีดิวเทอเรียมที่ให้พลังงานฟิวชันเทียบเท่าน้ำมันเบนซินถึง 300 ลิตร! ไม่มีก๊าซเรือนกระจก และไม่มีกากนิวเคลียร์อันตรายพันปีเหมือนฟิชชัน"
      },
