          "latex": "^2_1\\text{H} + ^3_1\\text{H} \\to ^4_2\\text{He}(3.5\\text{ MeV}) + ^1_0n(14.1\\text{ MeV}) + 17.6\\text{ MeV}",
          "name": "ปฏิกิริยาฟิวชันดิวเทอเรียม-ทริเทียม (D-T Fusion Reaction)",
          "desc": "ปฏิกิริยาฟิวชันที่มีพื้นที่หน้าตัดสูงสุดและจุดระเบิดติดง่ายที่สุดสำหรับเตาปฏิกรณ์บนโลก",
