        "validWhen": "การกักขังควาร์ก (Quark Confinement): ควาร์กไม่สามารถอยู่โดดเดี่ยวตามลำพังในธรรมชาติได้ การพยายามดึงควาร์กแยกออกจากกันจะใช้พลังงานสูงมากจนสร้างควาร์กคู่ใหม่ขึ้นมาแทนที่ทันที",
