        "diagramSvg": "<svg viewBox=\"0 0 460 140\" class=\"w-full h-36 bg-slate-900 rounded\" style=\"background: #0f172a; border: 1px solid rgba(255,255,255,0.1);\">\n      <!-- Quarks column -->\n      <rect x=\"30\" y=\"20\" width=\"80\" height=\"100\" rx=\"4\" fill=\"#450a0a\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n      <text x=\"70\" y=\"38\" fill=\"#f87171\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">ควาร์ก (Quarks)</text>\n      <text x=\"70\" y=\"60\" fill=\"#fca5a5\" font-size=\"9\" text-anchor=\"middle\">u (up)   c (charm)   t (top)</text>\n      <text x=\"70\" y=\"80\" fill=\"#fca5a5\" font-size=\"9\" text-anchor=\"middle\">d (down) s (strange) b (bottom)</text>\n      <text x=\"70\" y=\"105\" fill=\"#f87171\" font-size=\"8\" text-anchor=\"middle\">แรงเข้ม / ไฟฟ้า / อ่อน</text>\n\n      <!-- Leptons column -->\n      <rect x=\"125\" y=\"20\" width=\"80\" height=\"100\" rx=\"4\" fill=\"#172554\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n      <text x=\"165\" y=\"38\" fill=\"#60a5fa\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">เลปตอน (Leptons)</text>\n      <text x=\"165\" y=\"60\" fill=\"#93c5fd\" font-size=\"9\" text-anchor=\"middle\">e (อิเล็กตรอน) μ  τ</text>\n      <text x=\"165\" y=\"80\" fill=\"#93c5fd\" font-size=\"9\" text-anchor=\"middle\">ν_e    ν_μ    ν_τ</text>\n      <text x=\"165\" y=\"105\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">ไฟฟ้า / อ่อน</text>\n\n      <!-- Gauge bosons -->\n      <rect x=\"220\" y=\"20\" width=\"80\" height=\"100\" rx=\"4\" fill=\"#713f12\" stroke=\"#eab308\" stroke-width=\"1.5\"/>\n      <text x=\"260\" y=\"38\" fill=\"#facc15\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">เกจโบซอน</text>\n      <text x=\"260\" y=\"60\" fill=\"#fef08a\" font-size=\"9\" text-anchor=\"middle\">γ (โฟตอน)  g (กลูออน)</text>\n      <text x=\"260\" y=\"80\" fill=\"#fef08a\" font-size=\"9\" text-anchor=\"middle\">W⁺, W⁻, Z⁰</text>\n      <text x=\"260\" y=\"105\" fill=\"#facc15\" font-size=\"8\" text-anchor=\"middle\">อนุภาคสื่อแรง</text>\n\n      <!-- Higgs Boson -->\n      <rect x=\"315\" y=\"20\" width=\"115\" height=\"100\" rx=\"4\" fill=\"#3b0764\" stroke=\"#a855f7\" stroke-width=\"1.5\"/>\n      <text x=\"372\" y=\"45\" fill=\"#c084fc\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">ฮิกส์โบซอน (Higgs)</text>\n      <circle cx=\"372\" cy=\"72\" r=\"16\" fill=\"#a855f7\"/>\n      <text x=\"372\" y=\"77\" fill=\"#fff\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">H⁰</text>\n      <text x=\"372\" y=\"105\" fill=\"#e9d5ff\" font-size=\"8\" text-anchor=\"middle\">กำเนิดมวลสาร 125 GeV</text>\n    </svg>",
