      "titleTh": "มาตรวิทยาทางรังสี ปริมาณรังสีดูดกลืนและรังสีสมมูล",
      "titleEn": "Radiation Dosimetry: Becquerel, Gray & Sievert",
      "summary": "ทำความเข้าใจหน่วยวัดรังสี 3 ระดับอย่างแจ่มแจ้ง: แหล่งกำเนิดพ่นออกมากี่ครั้ง (Bq), ร่างกายดูดซับพลังงานกี่จูล (Gy), และเนื้อเยื่อเสียหายทางชีวภาพเท่าใด (Sv)",
      "definition": {
        "text": "มาตรวิทยาทางรังสี (Radiation Dosimetry) คือศาสตร์แห่งการวัดและประเมินผลกระทบของรังสีแตกตัวเป็นไอออนต่อสสารและสิ่งมีชีวิต เพื่อความปลอดภัยและการแพทย์ รังสีมีหน่วยวัดมาตรฐาน 3 ชั้นที่ต้องแยกแยะให้ชัดเจน: 1) กัมมันตภาพ (Activity: Bq): จำนวนการสลายตัวต่อวินาทีของแหล่งกำเนิดรังสี 2) ปริมาณรังสีดูดกลืน (Absorbed Dose: D, หน่วย เกรย์: Gray, 1 Gy = 1 J/kg): ปริมาณพลังงานรังสีที่ถูกถ่ายทอดลงสู่เนื้อเยื่อ 1 กิโลกรัม 3) ปริมาณรังสีสมมูล (Equivalent Dose: H, หน่วย ซีเวิร์ต: Sievert, 1 Sv = 1 J/kg): ปริมาณรังสีดูดกลืนคูณด้วยค่าน้ำหนักทางรังสี (Radiation Weighting Factor, $w_R$) เพื่อสะท้อนระดับความเสียหายทางชีววิทยาจริงของเซลล์สิ่งมีชีวิต"
      },
      "principle": {
        "text": "การจดจำและรูปแบบทางกายภาพ (Intuitive Mental Model):\n1. อุปมาอุปไมย 'ลูกปืนสไนเปอร์ vs ลูกเบสบอล':\n   - Activity (Bq): เปรียบเสมือน 'จำนวนลูกกระสุนที่ปืนยิงออกมาต่อวินาที'\n   - Absorbed Dose (Gy): เปรียบเสมือน 'พลังงานจลน์รวมของกระสุนที่ชนเป้าหมาย'\n   - Equivalent Dose (Sv): เปรียบเสมือน 'ความเสียหายของอวัยวะ'! ถ้าเป้าหมายโดนพลังงาน 1 จูลเท่ากัน: รังสีแกมมา/บีตา ($w_R = 1$) เหมือนโดนลูกปิงปองกระจายทั่วตัว แต่ รังสีแอลฟา ($w_R = 20$) เหมือนโดนกระสุนเจาะเกราะทะลวงทำลายล้างเฉพาะจุด! ดังนั้น 1 Gy ของแอลฟา = 20 Sv ของความเสียหาย!\n2. ระดับรังสีในชีวิตประจำวัน (Numbers to Remember):\n   - กินกล้วย 1 ลูก (มี ⁴⁰K): ได้รับรังสีจิ๋ว ~0.1 μSv (ไมโครซีเวิร์ต)\n   - เอ็กซเรย์ฟัน 1 ครั้ง: ~5 μSv\n   - เอ็กซเรย์ปอด (Chest X-Ray) 1 ครั้ง: ~0.1 mSv (มิลลิซีเวิร์ต)\n   - เที่ยวบินพาณิชย์ข้ามทวีป (รังสีคอสมิกบนฟ้า): ~0.04 mSv ต่อเที่ยวบิน\n   - รังสีพื้นหลังธรรมชาติที่มนุษย์ทุกคนได้รับต่อปี: ~2.4 - 3.0 mSv/ปี (ปลอดภัยสมบูรณ์)\n   - ขีดจำกัดความปลอดภัยสำหรับเจ้าหน้าที่รังสี: ไม่เกิน 20 mSv/ปี\n   - อาการป่วยจากรังสีเฉียบพลัน (Acute Radiation Sickness: คลื่นไส้ เม็ดเลือดขาวตก): เริ่มต้นที่ > 1,000 mSv (1.0 Sv)\n   - ปริมาณรังสีถึงตาย 50% (LD50): ~4.0 - 5.0 Sv"
      },
